// "Source" links of the popups point at the cited paragraph of https://5e24srd.com (src/data/links.ts, map
// generated by tools/build_srd_links.py).
import { describe, expect, it } from 'vitest'
import links from '../data/srd/links.json'
import { SRD_SITE, srdPath, srdUrl } from '../data/links'
import { rules } from '../data/rules'

const FOLDERS = [
  'playing-the-game/',
  'character-creation/',
  'character-origins/',
  'classes/',
  'equipment/',
  'feats/',
  'spells/',
]

describe('SRD links (5e24srd.com)', () => {
  it('every link starts with a known site folder and names an .html page', () => {
    const bad = Object.entries(links as Record<string, string>).filter(
      ([, url]) =>
        !FOLDERS.some((f) => url.startsWith(f)) || !/^[a-z0-9-]+\/[a-z0-9-]+\.html(#[a-z0-9_-]+)?$/.test(url),
    )
    expect(bad).toEqual([])
  })

  it('resolves known sections to their paragraph', () => {
    const at = (section: string, name?: string) => srdPath({ page: 1, section }, name)
    expect(at('Classes > Barbarian > Level 1: Rage')).toBe('classes/barbarian.html#level-1-rage')
    expect(at('Classes > Barbarian > Path of the Berserker > Level 3: Frenzy')).toBe(
      'classes/barbarian.html#level-3-frenzy',
    )
    expect(at('Classes > Fighter > Level 1: Weapon Mastery')).toBe('classes/fighter.html#level-1-weapon-mastery')
    expect(at('Weapons', 'Longsword')).toBe('equipment/weapons.html#martial-melee-weapons')
    expect(at('Spells', 'Fireball')).toBe('spells/spell-descriptions.html#fireball')
    expect(at('Feats > Origin Feats > Alert')).toBe('feats/index.html#alert')
    // The site has no Rules Glossary: a condition goes to the nearest paragraph of "Playing the Game".
    expect(at('Rules Glossary', 'Prone')).toBe('playing-the-game/combat.html#dropping-prone')
    expect(at('Rules Glossary', 'Grappled')).toMatch(/^playing-the-game\//)
  })

  it('uses the data entries as they are', () => {
    const fireball = [...rules.spells.values()].find((s) => s.name.en === 'Fireball')!
    expect(srdUrl(fireball.source, fireball.name.en)).toBe(SRD_SITE + 'spells/spell-descriptions.html#fireball')
    const longsword = [...rules.weapons.values()].find((w) => w.name.en === 'Longsword')!
    expect(srdUrl(longsword.source, longsword.name.en)).toContain('equipment/weapons.html#')
  })

  it('falls back to the official PDF page when the site lacks the chapter (monsters), else the home page', () => {
    expect(srdUrl({ page: 300, section: 'Monsters A–Z' }, 'Unknown')).toBe(
      'https://media.dndbeyond.com/compendium-images/srd/5.2/SRD_CC_v5.2.1.pdf#page=300',
    )
    expect(srdUrl(undefined)).toBe(SRD_SITE + 'index.html')
  })
})
